# owner: platform
"""Plain text absence notices for parents."""

from typing import Iterable, List

from rosterkit.models import Mark, Student


def _absent_days(student: Student, marks: Iterable[Mark]) -> List:
    found = set()
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(f"foreign mark: {mark.student_id}")
        if mark.status == "absent":
            found.add(mark.day)
    return sorted(found)


def _compose(name: str, days: List) -> str:
    unit = "day" if len(days) == 1 else "days"
    dates = ", ".join(when.isoformat() for when in days)
    return (
        f"Absence notice: {name} missed {len(days)} "
        f"{unit}. Dates: {dates}."
    )


def build_notice(student: Student, marks: Iterable[Mark]) -> str:
    """Short notice listing a student's absent days in order.

    Raises ValueError if a mark belongs to another student or
    if the student has no absences.
    """
    days = _absent_days(student, marks)
    if not days:
        raise ValueError("no absences to report")
    name = f"{student.first_name} {student.last_name}"
    return _compose(name, days)
EOF
cat > tests/test_notices.py <<'EOF'
# owner: platform
import unittest
from rosterkit.notices import build_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("s1", "Doe", "Jane", "A")


def mark(day, status="absent", who="s1"):
    return Mark(who, date(2026, 3, day), status)


class NoticeTests(unittest.TestCase):
    def test_names_count_and_sorted_dates(self):
        marks = [mark(9), mark(2), mark(5, "present")]
        text = build_notice(PUPIL, marks)
        self.assertIn("Jane Doe", text)
        self.assertIn("2 days", text)
        self.assertIn("2026-03-02, 2026-03-09", text)

    def test_single_day_is_singular(self):
        text = build_notice(PUPIL, [mark(4)])
        self.assertIn("1 day.", text)

    def test_duplicate_marks_count_once(self):
        text = build_notice(PUPIL, [mark(4), mark(4)])
        self.assertIn("1 day.", text)

    def test_foreign_mark_raises(self):
        marks = [mark(4), mark(5, who="s2")]
        with self.assertRaises(ValueError):
            build_notice(PUPIL, marks)

    def test_no_absences_raises(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [mark(4, "late")])

    def test_no_marks_raises(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [])
EOF
